    gr_output.capped_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if ((!valid_config) || (!valid_sample)) {
    gr_state.mode = GR_FAULT;
    gr_state.clean = 0U;
    gr_output.mode = GR_FAULT;
    gr_output.clean = 0U;
    gr_output.norm_rad_s = 0.0;
    gr_output.energy_rad2_s2 = 0.0;
    gr_output.capped_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

n = adcs_vec3_norm(gr_input.rate_rad_s);
gr_output.norm_rad_s = n;
gr_output.energy_rad2_s2 = adcs_vec3_dot(gr_input.rate_rad_s, gr_input.rate_rad_s);

if (n > gr_config.saturated_rad_s) {
    capped = adcs_vec3_scale(gr_input.rate_rad_s, gr_config.saturated_rad_s / n);
} else {
    capped = *gr_input.rate_rad_s;
}
gr_output.capped_rate_rad_s = capped;

if (fault_latched) {
    gr_state.mode = GR_FAULT;
    gr_state.clean = 0U;
    gr_output.mode = GR_FAULT;
    gr_output.clean = 0U;
    gr_output.norm_rad_s = 0.0;
    gr_output.energy_rad2_s2 = 0.0;
    gr_output.capped_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (n >= gr_config.saturated_rad_s) {
    gr_state.mode = GR_SATURATED;
    gr_state.clean = 0U;
    gr_output.mode = GR_SATURATED;
    gr_output.clean = 0U;
    return;
}

if ((n <= gr_config.recovered_rad_s) &&
    ((gr_state.mode == GR_SATURATED) || (gr_state.mode == GR_RECOVERING))) {
    gr_state.clean = gr_state.clean + 1U;
    if (gr_state.clean >= gr_config.required_clean) {
        gr_state.mode = GR_NOMINAL;
        gr_state.clean = gr_config.required_clean;
    } else {
        gr_state.mode = GR_RECOVERING;
    }
    gr_output.mode = gr_state.mode;
    gr_output.clean = gr_state.clean;
    return;
}

if ((n > gr_config.recovered_rad_s) && (n < gr_config.saturated_rad_s) &&
    ((gr_state.mode == GR_SATURATED) || (gr_state.mode == GR_RECOVERING))) {
    gr_state.mode = GR_SATURATED;
    gr_state.clean = 0U;
    gr_output.mode = GR_SATURATED;
    gr_output.clean = 0U;
    return;
}

if ((n < gr_config.saturated_rad_s) && (gr_state.mode == GR_NOMINAL)) {
    gr_output.mode = GR_NOMINAL;
    gr_output.clean = gr_state.clean;
    return;
}

gr_state.mode = GR_NOMINAL;
gr_state.clean = 0U;
gr_output.mode = GR_NOMINAL;
gr_output.clean = 0U;
